        playButton.classList.remove('hidden');
    });

    // Скрыть кнопку при начале воспроизведения (включая перемотку)
    video.addEventListener('play', () =&amp;gt; {
        playButton.classList.add('hidden');
    });

    // Скрыть кнопку, если видео уже играет при загрузке страницы
    if (!video.paused) {
