    /* Основные стили для контейнера */
    .video-container {
        width: 100%; /* Контейнер занимает всю ширину */
        max-width: 700px; /* Максимальная ширина контейнера */
        height: auto; /* Высота автоматически подстраивается */
        aspect-ratio: 16 / 9; /* Соотношение сторон 16:9 */
        position: relative; /* Для позиционирования кнопки */
        border: 1px solid #f0f0f0; /* Тонкая рамка */
        overflow: hidden; /* Скрыть всё, что выходит за пределы контейнера */
    }

    /* Видео */
    .fixed-size-video {
        width: 100%; /* Видео занимает всю ширину контейнера */
        height: 100%; /* Видео занимает всю высоту контейнера */
        display: block;
        object-fit: contain; /* Видео полностью помещается в контейнер без обрезки */
    }

    /* Кнопка воспроизведения */
    .play-button {
        position: absolute;
        top: 50%;
