	&amp;lt;!-- Кнопка воспроизведения --&amp;gt; &amp;lt;button class=&amp;quot;play-button&amp;quot; onclick=&amp;quot;playVideo()&amp;quot;&amp;gt;&amp;lt;/button&amp;gt;
&amp;lt;/div&amp;gt;
 &amp;lt;script&amp;gt;
    const video = document.querySelector('.fixed-size-video');
    const playButton = document.querySelector('.play-button');

    // Функция для воспроизведения видео
    function playVideo() {
        video.play(); // Запуск видео
        playButton.classList.add('hidden'); // Скрыть кнопку
    }

    // Показать кнопку при паузе
    video.addEventListener('pause', () =&amp;gt; {
        playButton.classList.remove('hidden');
    });

    // Скрыть кнопку при начале воспроизведения (включая перемотку)
    video.addEventListener('play', () =&amp;gt; {
        playButton.classList.add('hidden');
    });

    // Скрыть кнопку, если видео уже играет при загрузке страницы
    if (!video.paused) {
